<script setup lang="ts">
import {onMounted,ref,watch} from 'vue';import {useRouter} from 'vue-router';import {useStudies} from '../stores/studies';import {useResearch} from '../stores/research';import {useAuth} from '../stores/auth';import {useTask} from '../hooks/useTask';import {usePolling} from '../hooks/usePolling';import {directions} from '../constants/enums';import {date} from '../utils/format';import PageHeading from '../components/common/PageHeading.vue';import ErrorNotice from '../components/common/ErrorNotice.vue';import StatusBadge from '../components/common/StatusBadge.vue';import StudySelect from '../components/StudySelect.vue';const study=useStudies(),research=useResearch(),auth=useAuth(),router=useRouter(),{error,busy,perform}=useTask(),name=ref('芦芯展厅 · 第一轮材料权衡'),weights=ref<Record<string,number>>({}),concentration=ref(40),seed=ref(20261112);watch(()=>study.criteria,()=>{weights.value=Object.fromEntries(study.criteria.map(c=>[c.code,c.center_weight]))},{deep:true});onMounted(()=>perform(async()=>{await study.load();await study.loadCriteria();await research.loadRuns()}));usePolling(()=>research.loadRuns());async function submit(){await research.queue({study_id:study.selected,name:name.value,center_weights:weights.value,concentration:concentration.value,repeats:1000,seed:seed.value});name.value='芦芯展厅 · 复核 '+new Date().toLocaleTimeString()}async function read(id:number){await research.select(id);router.push('/results')}
</script><template><PageHeading no="03" title="权衡配置" sub="把一组偏好写明，冻结候选与指标，再让1000个权重情景检验名次变化。"/><ErrorNotice :error="error"/><div class="run-spread"><section><StudySelect/><form class="run-form" @submit.prevent="perform(submit)"><label>研究名称<input v-model="name" minLength="2" maxLength="140" required/></label><h2 class="ruled-title">正中心权重 <small>后台归一化至和为1</small></h2><div class="weight-input" v-for="c in study.criteria" :key="c.id"><div><b>{{c.name}}</b><small>{{directions[c.direction]}} / {{c.unit}}</small></div><input :aria-label="c.name+'中心权重'" v-model.number="weights[c.code]" type="number" min="0" max="1000" step="any" required/></div><p v-if="!study.criteria.length" class="empty">请先到“试样与口径”登记指标。无指标的任务会保留失败原因。</p><div class="two-col"><label>Dirichlet集中度 κ<input v-model.number="concentration" type="number" min=".1" max="10000" step="any" required/></label><label>随机种子<input v-model.number="seed" type="number" min="0" max="2147483647" step="1" required/></label></div><div class="configuration-note"><b>1000次独立偏好情景</b><p>α = κ × 归一化中心权重。κ越大，情景越靠近中心；κ不是样本量或置信水平。每次重新计算TOPSIS与平均并列名次。</p></div><button class="primary" :disabled="busy||!auth.canEdit">{{busy?'提交中…':'冻结并排队计算 →'}}</button><p v-if="!auth.canEdit" class="muted">观察员可以阅读结果，请研究员提交计算。</p></form><aside class="margin-note"><b>使用之前，确认三件事</b><p>权重表达研究组的偏好。方向由本研究指标口径决定。候选增删、指标平移都可能改变归一化与名次。</p><p>情景权重出现数值0时按合法非负权重处理；要求严格为正的是中心权重。所有情景原样保留。</p></aside></section><section><h2 class="ruled-title">研究演算队列 <small>{{research.runs.length}}项</small></h2><div v-if="!research.runs.length" class="empty"><h3>尚无已提交的研究。</h3><p>左侧写下偏好后，后台会保存快照并执行真实计算。完成结果不会由seed预置。</p></div><article v-for="r in research.runs" :key="r.id" class="run-entry"><div class="entry-line"><small>STUDY {{String(r.id).padStart(3,'0')}}</small><StatusBadge :status="r.status"/></div><h3>{{r.name}}</h3><p>{{r.summary.samples}}份候选 / {{r.summary.criteria}}项指标 · κ {{r.concentration}} · {{r.repeats}}情景</p><small>{{date(r.created_at)}} / seed {{r.seed}}</small><p v-if="r.error" class="error-text">{{r.error}}</p><button v-if="r.status==='completed'" class="text-link" @click="perform(()=>read(r.id))">阅读贴近度与扰动结果 ↗</button><p v-if="['queued','running'].includes(r.status)" class="working">后台持续计算，队列每2.5秒刷新。</p></article></section></div></template>